"""Original cardiovascular bedside reasoning: venous waveforms and heart sounds."""
from qbank_authoring import question,ref
rows=[]
JV=ref('Stanford Medicine 25: neck veins and JVP','https://stanfordmedicine25.stanford.edu/the25/neck-exam-jugular-venous-pressure-measurement.html')
HS=ref('Stanford Medicine 25: cardiac second sounds','https://stanfordmedicine25.stanford.edu/the25/cardiac.html')
CE=ref('Cardiology Explained: cardiovascular examination','https://www.ncbi.nlm.nih.gov/books/NBK2213/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('Which bedside feature favors a jugular venous pulsation over a carotid pulsation?', 'A nonpalpable multiphasic waveform that changes with position and respiration',[
 ('A single brisk palpable upstroke persisting despite gentle venous compression','This favors an arterial pulse.'),('A pulsation independent of posture and respiration','This is less characteristic of the venous column.'),('A pulse requiring firm bilateral carotid pressure to identify','That is unsafe and does not describe a venous examination.')],
 'Identify the vessel before measuring its height','**Venous pulsation reflects right-atrial pressure changes transmitted to the neck.**',['Use tangential light and adjust the patient’s angle.','The venous top may lie outside view when the position is unsuitable.'],'**Measure and interpret the column in a standardized way.**',['Avoid simultaneous bilateral carotid compression.','Do not assume an unseen venous column is normal.'],[['Jugular','Multiphasic/nonpalpable/position-dependent'],['Carotid','Single palpable arterial upstroke'],['Technique','Position and lighting']],[JV])

q('Which jugular waveform is absent when coordinated right-atrial contraction is lost in atrial fibrillation?', 'The a wave',[
 ('The v wave','Venous filling during ventricular systole can still produce this wave.'),('The y descent','Early atrial emptying can still occur.'),('All venous pressure variation','Other transmitted cardiac events can remain visible.')],
 'Link each waveform to its mechanical event','**The a wave reflects atrial contraction.**',['AF removes coordinated atrial systole.','The appearance is also influenced by right-heart pressures and valve disease.'],'**Interpret the waveform with rhythm confirmation.**',['Use the ECG and carotid timing when needed.','Do not diagnose AF from waveform absence alone.'],[['a','Atrial contraction'],['v','Atrial filling during ventricular systole'],['y','Atrial emptying']],[JV])

q('Intermittent very large jugular a waves occur in a patient with complete AV block. What is their mechanism?', 'Atrial contraction against a closed tricuspid valve during AV dissociation',[
 ('Systolic regurgitation through an incompetent tricuspid valve','This produces prominent systolic v/cv waves rather than intermittent cannon a waves.'),('Absence of atrial contraction','That removes the a wave rather than enlarging it.'),('Normal venous filling with no rhythm relationship','The timing against valve closure is central.')],
 'Cannon waves reveal a timing problem','**AV dissociation can place atrial contraction during ventricular systole.**',['The closed valve raises the transmitted atrial pressure.','Other AV-dissociation states can also produce cannon waves.'],'**Confirm the rhythm and assess hemodynamic consequences.**',['A regular giant a wave can have a different mechanism such as impaired right-sided filling.','Use ECG correlation rather than waveform size alone.'],[['Cannon a','Atrial contraction against closed valve'],['Giant v','Regurgitant systolic filling'],['AF','No organized a wave']],[JV],style='clinical_scenario')

q('A patient has large systolic jugular waves and a pulsatile liver with a lower-sternal holosystolic murmur. Which lesion best fits?', 'Tricuspid regurgitation',[
 ('Mitral stenosis','This does not directly produce the described systemic venous systolic reflux.'),('Aortic stenosis','Its primary murmur and pulse pattern differ.'),('Isolated pulmonary stenosis','It can produce large a waves from RV filling resistance, but not the same regurgitant systolic pattern.')],
 'Systolic backflow can ventricularize the venous waveform','**TR transmits RV systolic pressure toward the right atrium and systemic veins.**',['The liver can show true expansile systolic pulsation.','Severity and loading conditions influence signs.'],'**Confirm anatomy and severity with echocardiography.**',['Assess RV function, pulmonary pressures and the cause.','Differentiate transmitted movement from true hepatic expansion.'],[['Jugular','Large v/cv wave'],['Liver','Systolic pulsation'],['Valve','Tricuspid regurgitation']],[JV,CE],style='clinical_scenario')

q('A sustained inspiratory rise in JVP is observed. What is the best interpretation?', 'Kussmaul sign, suggesting impaired right-heart accommodation of increased venous return',[
 ('Normal inspiratory venous-pressure behavior','JVP usually falls with spontaneous inspiration.'),('A sign uniquely diagnostic of constrictive pericarditis','Restriction, RV infarction and other right-sided filling problems can produce it.'),('A measurement of pulsus paradoxus','That concerns respiratory variation in arterial systolic pressure.')],
 'Respiration tests the ability to accept venous return','**A constrained right heart may fail to accommodate the inspiratory inflow increase.**',['Interpret posture, breathing and the whole hemodynamic context.','Do not confuse venous and arterial respiratory signs.'],'**Assess for constrictive, restrictive and RV disease.**',['Use echo and other testing to distinguish causes.','Uncomplicated tamponade more often has a different filling pattern; exceptions and mixed disease occur.'],[['Kussmaul','Inspiratory JVP rise'],['Normal','Inspiratory fall'],['Differential','Several impaired-filling states']],[JV])

q('Which jugular pattern favors constrictive pericarditis over uncomplicated cardiac tamponade?', 'A prominent rapid y descent',[
 ('A blunted y descent','This is more typical of tamponade-impaired early filling.'),('Absence of every systolic venous wave','This is not the defining distinction.'),('No change in any waveform despite altered filling','The filling dynamics are precisely what create the distinction.')],
 'Early diastolic filling behaves differently in the two syndromes','**Constriction can permit rapid initial filling followed by abrupt limitation.**',['Tamponade restricts filling through the cycle and commonly blunts the y descent.','Mixed and atypical disease can complicate the pattern.'],'**Use the waveform as one component of a multimodal assessment.**',['Correlate with echo, respiratory ventricular interaction and the clinical setting.','Do not exclude a dangerous effusion from a difficult neck examination.'],[['Constriction','Rapid y descent'],['Tamponade','Blunted y descent'],['Diagnosis','Integrated hemodynamics']],[JV,CE])

q('Firm sustained abdominal pressure produces a persistent rise in JVP rather than a brief transient rise. What does this support?', 'Limited right-heart ability to accommodate increased venous return',[
 ('A normal response in every healthy adult','A sustained rise suggests abnormal hemodynamic reserve in context.'),('A specific diagnosis of cirrhosis without cardiac involvement','The maneuver tests a venous/cardiac response, not a liver diagnosis.'),('A direct measurement of left-ventricular ejection fraction','It does not quantify EF.')],
 'The abdominojugular response is a physiological stress maneuver','**Increased venous return can reveal elevated filling pressure or limited reserve.**',['Technique and sustained observation matter.','Pain or breath holding can distort the response.'],'**Interpret alongside the baseline JVP and congestion findings.**',['Ask the patient to breathe normally.','Use echocardiography when structural/function information is needed.'],[['Stimulus','Abdominal pressure'],['Abnormal response','Sustained JVP rise'],['Limit','Not a valve/EF-specific test']],[JV])

q('A diffuse apical impulse is displaced laterally and inferiorly. Which finding is most supported?', 'Left-ventricular enlargement or altered cardiac position, requiring contextual confirmation',[
 ('A pure RV pressure load as the only explanation','That more typically produces a parasternal heave.'),('A normal LV size is guaranteed','Displacement can support enlargement, although thoracic factors also matter.'),('Severe aortic stenosis is uniquely established','Several causes of LV enlargement can alter the impulse.')],
 'Palpation locates and characterizes the mechanical impulse','**Position, area and duration convey different information.**',['Body habitus, lung disease and chest anatomy can influence the palpable location.','A sustained impulse can suggest pressure loading while a diffuse hyperdynamic impulse suggests a different pattern.'],'**Correlate with other signs and imaging.**',['Assess parasternal RV activity separately.','Do not infer exact chamber dimensions from palpation alone.'],[['Location','Possible LV enlargement/position shift'],['Parasternal heave','RV load clue'],['Confirmation','Echo when indicated']],[CE],style='clinical_scenario')

q('An S3 is heard just after S2 in an older adult with dyspnea and a displaced apex. Which mechanism best fits?', 'Rapid early diastolic ventricular filling with a pathological volume/filling-pressure context',[
 ('Atrial contraction into a stiff ventricle','This produces S4, late in diastole.'),('Aortic valve closure','This contributes to S2 itself.'),('A systolic ejection click','That occurs earlier in the cardiac cycle.')],
 'Timing distinguishes extra sounds','**S3 occurs during early filling.**',['It may be physiological in younger people, but context changes its implication.','In an older symptomatic patient it can support ventricular dysfunction or volume overload.'],'**Assess the whole heart-failure syndrome.**',['Confirm rhythm, valve lesions and ventricular function.','Do not diagnose a specific EF phenotype from S3 alone.'],[['S3','Early diastole'],['S4','Late diastole/atrial contraction'],['Context','Age and symptoms matter']],[CE],style='clinical_scenario')

q('Why is a true S4 generally absent during atrial fibrillation?', 'It requires coordinated atrial contraction',[
 ('AF prevents all early ventricular filling','Early filling can continue without organized atrial systole.'),('AF always abolishes S2','Semilunar valve closure still occurs.'),('S4 is produced by tricuspid regurgitation during systole','S4 is a late-diastolic filling sound.')],
 'The sound depends on an atrial mechanical contribution','**S4 is associated with atrial contraction against a less compliant ventricle.**',['A stiff ventricle can remain present in AF without producing a true atrial gallop.','Tachycardia can make sound timing difficult.'],'**Correlate the auscultation with the rhythm.**',['Do not label any low-frequency extra sound as S4 without timing it.','Use the carotid pulse and repeated listening when needed.'],[['Required event','Atrial contraction'],['AF','No coordinated atrial systole'],['S4','Late diastolic']],[CE])

q('Wide splitting of S2 that changes little with respiration, with a pulmonary flow murmur, most strongly suggests which lesion?', 'Atrial septal defect',[
 ('Left bundle branch block','This can produce paradoxical rather than the characteristic fixed split.'),('Severe aortic stenosis','Delayed A2 can also produce paradoxical splitting.'),('Mitral regurgitation alone','This does not characteristically produce fixed wide splitting.')],
 'Fixed splitting points to altered right-sided filling dynamics','**ASD can maintain relatively constant RV filling across respiration.**',['The systolic murmur is often increased flow across the pulmonary valve rather than flow through the atrial defect.','Other examination findings depend on shunt size and pulmonary pressure.'],'**Confirm the suspected lesion with echocardiography.**',['Assess right-heart size and pulmonary vascular consequences.','Do not assume every wide split is fixed.'],[['ASD','Wide fixed split'],['RBBB/PS','Wide but usually respiratory variation'],['LBBB/severe AS','Possible paradoxical split']],[HS,CE])

q('S2 splits during expiration and becomes single during inspiration in a patient with LBBB. Which mechanism explains this?', 'Delayed A2 causes reversed or paradoxical splitting',[
 ('Delayed P2 with otherwise normal A2 timing','This usually widens normal-order splitting.'),('Premature A2 from rapid LV ejection','The described mechanism is delayed LV activation/closure.'),('A fixed split caused by an ASD','Fixed splitting does not show this characteristic respiratory disappearance.')],
 'Identify which component is delayed','**LBBB can delay LV ejection completion and aortic closure.**',['Inspiration delays P2 toward the already late A2, narrowing the reversed gap.','Severe aortic stenosis can produce a similar timing pattern.'],'**Correlate with ECG and valve assessment.**',['Listening location and intensity can make components hard to identify.','Use the pattern as a clue rather than a severity measurement.'],[['Expiration','P2 then delayed A2'],['Inspiration','P2 delay narrows gap'],['Pattern','Paradoxical split']],[HS,CE],style='clinical_scenario')
